//! Explicit local report export; filenames and file contents are generated by TokLens.
use super::{AppState, CommandError, dto::ClientParam, storage};
use crate::{
    collectors::CollectorRoots,
    usage::{analytics::AnalyticsFilter, report::ReportFormat, time::now_ms},
};
use serde::{Deserialize, Serialize};
use std::{
    fs::OpenOptions,
    io::Write,
    path::Path,
    sync::atomic::{AtomicU64, Ordering},
};
use tauri::{AppHandle, Manager};

static NEXT_REPORT: AtomicU64 = AtomicU64::new(0);

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ExportArgs {
    directory: String,
    format: ReportFormat,
    from_ms: Option<i64>,
    to_ms: i64,
    client: Option<ClientParam>,
    include_estimated: bool,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportResult {
    path: String,
    row_count: usize,
    untimed_requests: i64,
    excluded_estimated_requests: i64,
}

/// The caller supplies a directory, never a filename that could overwrite another file.
fn save_report(
    directory: &Path,
    format: ReportFormat,
    contents: &str,
    generated_at_ms: i64,
    roots: &CollectorRoots,
) -> Result<String, CommandError> {
    let directory = storage::validate_target(directory, roots).map_err(CommandError::new)?;
    std::fs::create_dir_all(&directory)
        .map_err(|_| CommandError::new("无法创建导出目录，请检查路径和写入权限"))?;
    // Recheck junctions after creation before opening the application-generated file.
    let directory = storage::validate_target(&directory, roots).map_err(CommandError::new)?;
    for _ in 0..100 {
        let sequence = NEXT_REPORT.fetch_add(1, Ordering::Relaxed);
        let path = directory.join(format!(
            "toklens-report-{generated_at_ms}-{sequence}.{}",
            format.extension()
        ));
        let mut file = match OpenOptions::new().write(true).create_new(true).open(&path) {
            Ok(file) => file,
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(_) => {
                return Err(CommandError::new(
                    "无法保存报告，请检查目录写入权限与磁盘空间",
                ));
            }
        };
        if file
            .write_all(contents.as_bytes())
            .and_then(|()| file.sync_all())
            .is_err()
        {
            drop(file);
            let cleanup = std::fs::remove_file(&path);
            return Err(CommandError::new(if cleanup.is_err() {
                "报告保存失败，可能留下不完整的报告文件，请检查导出目录"
            } else {
                "报告保存失败，请检查磁盘空间后重试"
            }));
        }
        return Ok(storage::display_path(&path));
    }
    Err(CommandError::new("无法生成唯一报告文件名，请稍后重试"))
}

#[tauri::command]
pub async fn export_statistics(
    app: AppHandle,
    args: ExportArgs,
) -> Result<ExportResult, CommandError> {
    tauri::async_runtime::spawn_blocking(move || {
        let filter = AnalyticsFilter {
            from_ms: args.from_ms,
            to_ms: Some(args.to_ms),
            client: args.client.map(Into::into),
            project_path: None,
        };
        let generated_at_ms = now_ms();
        let state = app.state::<AppState>();
        let _export = state.activity.begin_export().map_err(CommandError::new)?;
        let report =
            state
                .store()?
                .statistics_report(&filter, args.include_estimated, generated_at_ms)?;
        let contents = report.render(args.format)?;
        let path = save_report(
            Path::new(&args.directory),
            args.format,
            &contents,
            generated_at_ms,
            &CollectorRoots::from_environment(),
        )?;
        Ok(ExportResult {
            path,
            row_count: report.rows.len(),
            untimed_requests: report.metadata.untimed_requests,
            excluded_estimated_requests: report.metadata.excluded_estimated_requests,
        })
    })
    .await
    .map_err(|_| CommandError::new("报告导出任务未能完成，请重试"))?
}

#[cfg(test)]
mod tests {
    use super::*;
    static NEXT_TEST: AtomicU64 = AtomicU64::new(0);
    struct Directory(std::path::PathBuf);
    impl Directory {
        fn new() -> Self {
            let path = std::env::temp_dir().join(format!(
                "toklens-export-{}-{}",
                std::process::id(),
                NEXT_TEST.fetch_add(1, Ordering::Relaxed)
            ));
            std::fs::create_dir_all(&path).expect("synthetic directory");
            Self(path)
        }
    }
    impl Drop for Directory {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    #[test]
    fn saves_unique_reports_without_overwriting_existing_files() {
        let directory = Directory::new();
        let roots = CollectorRoots::default();
        let first = save_report(
            &directory.0,
            ReportFormat::Json,
            "synthetic report A",
            123,
            &roots,
        )
        .expect("save A");
        let second = save_report(
            &directory.0,
            ReportFormat::Json,
            "synthetic report B",
            123,
            &roots,
        )
        .expect("save B");
        assert_ne!(first, second);
        assert_eq!(
            std::fs::read_to_string(first).expect("read A"),
            "synthetic report A"
        );
        assert_eq!(
            std::fs::read_to_string(second).expect("read B"),
            "synthetic report B"
        );
    }
    #[test]
    fn refuses_relative_paths_and_client_directories_before_writing() {
        let directory = Directory::new();
        let roots = CollectorRoots {
            codex: Some(directory.0.join("client")),
            ..Default::default()
        };
        assert!(
            save_report(
                Path::new("relative-reports"),
                ReportFormat::Csv,
                "data",
                1,
                &roots
            )
            .is_err()
        );
        assert!(
            save_report(
                &directory.0.join("client/reports"),
                ReportFormat::Csv,
                "data",
                1,
                &roots
            )
            .is_err()
        );
        assert!(!directory.0.join("client").exists());
    }
}
